package expo.modules.eventcliprender.realmedia
import org.junit.Test
import org.junit.Assert.*
import java.io.File
import java.io.FileOutputStream
import java.nio.file.Files
import java.util.UUID
import java.util.concurrent.atomic.AtomicBoolean

class ProductSaveTransactionTest {
 private class Death:Error()
 private class Destination(val root:File):SaveDestination {
  val rows=linkedMapOf<String,PendingSaveRow>();var inserts=0;var deletes=0;var available=Long.MAX_VALUE;var throwAfterCommit=false
  override fun freeBytes()=available
  override fun insert(saveId:String):String{val token=UUID.randomUUID().toString();rows[token]=PendingSaveRow(token,saveId,true);inserts++;return token}
  override fun find(saveId:String,token:String?):PendingSaveRow?=if(token==null)rows.values.filter{it.saveId==saveId}.singleOrNull()else rows[token]?.also{require(it.saveId==saveId)}
  override fun open(row:PendingSaveRow):SaveOutput {require(row.pending&&rows[row.token]==row);val out=FileOutputStream(File(root,row.token));return object:SaveOutput{override val stream=out;override fun sync(){out.fd.sync()};override fun close(){out.close()}}}
  override fun openRead(row:PendingSaveRow)=File(root,row.token).inputStream()
  override fun publish(row:PendingSaveRow){rows[row.token]=row.copy(pending=false);if(throwAfterCommit)throw java.io.IOException("synthetic acknowledgement failure")}
  override fun deletePending(row:PendingSaveRow){if(rows[row.token]?.pending==true){File(root,row.token).delete();rows.remove(row.token);deletes++}}
 }
 private fun run(block:(File,File,Destination,SaveSource)->Unit){val root=Files.createTempDirectory("eventclip-save-test").toFile();try{val metadata=File(root,"exports").apply{mkdir()};val public=File(root,"mock-public").apply{mkdir()};val source=File(metadata,"${UUID.randomUUID()}.mp4").apply{writeBytes(ByteArray(150000){(it%251).toByte()})};block(root,metadata,Destination(public),SaveSource(source.nameWithoutExtension,source,source.length(),ProductPrivateFiles.hash(source)))}finally{root.deleteRecursively()}}
 @Test fun exactCopyCommitsBeforeSavedAndNeverChangesPrivate(){run{_,m,d,s->val store=ProductDeliveryStore(m);val before=s.file.readBytes();assertEquals("SAVED",ProductSaveTransaction(store,d).save(s,AtomicBoolean(false)){});val p=store.info(s.exportId);assertEquals("SAVED",p.getProperty("saveState"));val row=d.rows.getValue(p.getProperty("savedUri"));assertFalse(row.pending);assertArrayEquals(before,d.openRead(row).use{it.readBytes()});assertArrayEquals(before,s.file.readBytes());assertEquals(0,d.deletes)}}
 @Test fun cancellationMidCopyRemovesOnlyPendingAndKeepsPrivate(){run{_,m,d,s->val store=ProductDeliveryStore(m);val flag=AtomicBoolean(false);try{ProductSaveTransaction(store,d).save(s,flag){flag.set(true)};fail()}catch(_:SaveCancelled){};assertTrue(d.rows.isEmpty());assertEquals(1,d.deletes);assertTrue(s.file.isFile);assertEquals("SAVE_FAILED",store.info(s.exportId).getProperty("saveState"))}}
 @Test fun processDeathAfterInsertBeforeUriRecordFindsOnlyRegisteredName(){run{_,m,d,s->val unrelated=UUID.randomUUID().toString();d.insert(unrelated);val store=ProductDeliveryStore(m);try{ProductSaveTransaction(store,d){if(it=="SAVE_AFTER_INSERT_BEFORE_RECORD")throw Death()}.save(s,AtomicBoolean(false)){};fail()}catch(_:Death){};ProductSaveTransaction(ProductDeliveryStore(m),d).recover();assertEquals(1,d.rows.size);assertEquals(unrelated,d.rows.values.single().saveId);assertEquals("SAVE_FAILED",store.info(s.exportId).getProperty("saveState"))}}
 @Test fun interruptedCheckpointsBeforeCommitCleanAndAfterCommitRetain(){for(point in listOf("SAVE_AFTER_BEGIN","SAVE_AFTER_COPYING","SAVE_AFTER_PUBLISHING","SAVE_AFTER_PROVIDER_COMMIT","SAVE_AFTER_METADATA")){run{_,m,d,s->val check:(String)->Unit={if(it==point)throw Death()};val store=ProductDeliveryStore(m,check);try{ProductSaveTransaction(store,d,check).save(s,AtomicBoolean(false)){};fail()}catch(_:Death){};val recovered=ProductDeliveryStore(m);ProductSaveTransaction(recovered,d).recover();if(point in listOf("SAVE_AFTER_PROVIDER_COMMIT","SAVE_AFTER_METADATA")){assertEquals("SAVED",recovered.info(s.exportId).getProperty("saveState"));assertEquals(1,d.rows.size);assertFalse(d.rows.values.single().pending);assertEquals(0,d.deletes)}else{assertEquals("SAVE_FAILED",recovered.info(s.exportId).getProperty("saveState"));assertTrue(d.rows.isEmpty())};assertTrue(s.file.exists())}}}
 @Test fun providerCommitAcknowledgementFailureDoesNotDeletePublicCopy(){run{_,m,d,s->d.throwAfterCommit=true;val store=ProductDeliveryStore(m);assertEquals("SAVED",ProductSaveTransaction(store,d).save(s,AtomicBoolean(false)){});assertEquals(0,d.deletes);assertFalse(d.rows.values.single().pending)}}
 @Test fun damagedCommittedPublicRowIsNotDeletedOrClaimedSaved(){run{_,m,d,s->val store=ProductDeliveryStore(m);val j=store.begin(s);val token=d.insert(j.getProperty("saveId"));store.update(j,"COPYING",token);val row=d.rows.getValue(token);d.open(row).use{it.stream.write(byteArrayOf(1,2,3))};d.publish(row);ProductSaveTransaction(store,d).recover();assertEquals("SAVE_FAILED",store.info(s.exportId).getProperty("saveState"));assertEquals(1,d.rows.size);assertEquals(0,d.deletes)}}
 @Test fun advisorySeparatePerFileNotConsentAndNeverSavePrerequisite(){run{_,m,d,s->val store=ProductDeliveryStore(m);assertEquals("false",store.info(s.exportId).getProperty("infoShown"));ProductSaveTransaction(store,d).save(s,AtomicBoolean(false)){};assertEquals("false",store.info(s.exportId).getProperty("firstShareContinued"));store.informationPresented(s.exportId);assertEquals("false",store.info(s.exportId).getProperty("firstShareContinued"));store.firstShareContinued(s.exportId);val reopen=ProductDeliveryStore(m);assertEquals("true",reopen.info(s.exportId).getProperty("infoShown"));assertEquals("true",reopen.info(s.exportId).getProperty("firstShareContinued"));val other=UUID.randomUUID().toString();assertEquals("false",reopen.info(other).getProperty("infoShown"));assertEquals("false",reopen.info(other).getProperty("firstShareContinued"));assertEquals("SAVED",reopen.info(s.exportId).getProperty("saveState"))}}
 @Test fun duplicateSavesIdempotentAndSpaceChecksPreservePrivate(){run{_,m,d,s->val store=ProductDeliveryStore(m);d.available=0;try{ProductSaveTransaction(store,d).save(s,AtomicBoolean(false)){};fail()}catch(_:FoundationFailure){};assertEquals(0,d.inserts);d.available=Long.MAX_VALUE;val transaction=ProductSaveTransaction(store,d);transaction.save(s,AtomicBoolean(false)){};transaction.save(s,AtomicBoolean(false)){};assertEquals(1,d.inserts);assertTrue(s.file.exists())}}
 @Test fun storageLostDuringCopyCleansPartial(){run{_,m,d,s->val store=ProductDeliveryStore(m);try{ProductSaveTransaction(store,d).save(s,AtomicBoolean(false)){d.available=0};fail()}catch(_:FoundationFailure){};assertTrue(d.rows.isEmpty());assertTrue(s.file.exists());assertEquals("SAVE_FAILED",store.info(s.exportId).getProperty("saveState"))}}
 @Test fun wrongSourceHashFailsBeforeAnyPublicInsert(){run{_,m,d,s->try{ProductSaveTransaction(ProductDeliveryStore(m),d).save(s.copy(sha256="f".repeat(64)),AtomicBoolean(false)){};fail()}catch(_:IllegalArgumentException){};assertEquals(0,d.inserts);assertTrue(s.file.exists())}}
}
